/* ============================================================
   MISSION HERO — mission-hero.module.css
   Matches: .mission-page-banner on our-mission.html
   ============================================================ */

.section {
  background-color: #0000;
  padding-top: 4rem;
  padding-bottom: 4rem;
  font-weight: 400;
  text-decoration: none;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 2rem;
  padding-right: 2rem;
}

.inner {
  text-align: center;
  max-width: 70rem;
  margin-left: auto;
  margin-right: auto;
}

/* ── Badge (.missionsubott) ── */
.badge {
  background-color: var(--color-accent-bg);
  border: 1px solid var(--color-brand-cyan);
  border-radius: 20px;
  margin-bottom: 17px;
  padding: 0 13px;
  line-height: 14px;
  display: inline-flex;
  align-items: center;
}

.badgeText {
  font-size: 12px;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-weight: 700;
  background-image: linear-gradient(90deg, #21cfff, #019ae6);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  padding-top: 6px;
  padding-bottom: 6px;
  margin: 0;
}

/* ── Heading (.web-ban-title) ── */
.heading {
  color: var(--color-brand-navy);
  margin-top: 0;
  margin-bottom: 10px;
  padding: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 40px;
  font-weight: 700;
  line-height: 1.25;
  text-decoration: none;
}

/* ── Subtitle (.h1-season-seeing.web-h1) ── */
.subtitle {
  color: var(--color-text-secondary);
  max-width: 53rem;
  margin-left: auto;
  margin-right: auto;
  margin-top: 0;
  padding-left: 1.5rem;
  padding-right: 1.5rem;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin-bottom: 0;
}

/* ── Stat badges wrapper (.web-job-attention) ── */
.badgeGridWrap {
  justify-content: center;
  align-items: center;
  margin-top: 2rem;
  padding-left: 0;
  padding-right: 0;
  font-weight: 400;
  text-decoration: none;
  display: flex;
}

/* ── Badges row (.web-ban-grid.mob-2grid) ── */
.badgeGrid {
  grid-column-gap: 16px;
  grid-row-gap: 16px;
  flex: 0 auto;
  width: auto;
  display: flex;
}

/* ── Individual badge (.web-grid-box) ── */
.statBadge {
  grid-column-gap: 10px;
  grid-row-gap: 10px;
  background-color: #fff;
  border-radius: 10px;
  align-items: center;
  width: auto;
  padding: 15px;
  transition: opacity 0.5s ease, transform 0.5s ease;
  display: flex;
  box-shadow: var(--shadow-card);
}

.statIcon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.statLabel {
  color: var(--color-text-primary);
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 15px;
  font-weight: 500;
  line-height: 1.3;
  margin: 0;
  text-align: left;
}

/* ── CTA buttons ── */
.ctaRow {
  justify-content: center;
  align-items: center;
  margin-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0;
}

/* First button: Book a Demo (.navy-arrow-btn.margin-left-0) */
.ctaPrimary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-color: var(--color-text-primary);
  background-image: url('/images/webflow/Group-46729-1.svg');
  background-position: 94%;
  background-repeat: no-repeat;
  background-size: auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-left: 0;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
}

.ctaPrimary:hover {
  color: var(--color-brand-blue);
  background-color: var(--color-accent-bg-hover);
}

/* Second button: Talk to Our Team (.a-gulf-book.margin-left) */
.ctaSecondary {
  color: #fff;
  width: auto;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 1rem;
  background-image: url('/images/webflow/Group-46729-2.svg'), linear-gradient(90deg, #21cfff, #019ae6);
  background-position: 93%, 0 0;
  background-repeat: no-repeat, repeat;
  background-size: auto, auto;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  justify-content: center;
  align-items: center;
  margin-left: 1.25rem;
  padding: 0.75rem 3rem 0.75rem 1.25rem;
  font-weight: 700;
  line-height: 1.75rem;
  text-decoration: none;
  display: inline-flex;
  box-shadow: var(--shadow-card);
}

.ctaSecondary:hover {
  background-color: var(--color-brand-navy);
  background-image: url('/images/webflow/Group-46729-2.svg');
  background-repeat: no-repeat;
  background-size: auto;
}

/* ── 2-col navy content grid (.mission-ban-grid) ── */
.contentGrid {
  display: grid;
  grid-column-gap: 20px;
  grid-row-gap: 20px;
  grid-template-columns: 1fr 1fr;
  padding-top: 60px;
}

/* Each navy card (.mission-bangrid-outer) */
.contentCol {
  background-color: var(--color-text-primary);
  border-radius: 20px;
  padding: 40px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.contentHeading {
  color: #fff;
  text-align: left;
  margin-top: 0;
  margin-bottom: 0;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 25px;
  font-weight: 700;
  line-height: 1.35;
  text-transform: capitalize;
}

.contentPara {
  color: rgba(255, 255, 255, 0.8);
  text-align: left;
  font-family: var(--font-roobert), Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 28px;
  margin: 0;
}

/* ============================================================
   min-width: 1280px
   ============================================================ */
@media screen and (min-width: 1280px) {
  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   min-width: 1440px
   ============================================================ */
@media screen and (min-width: 1440px) {
  .statBadge {
    padding: 20px;
  }
}

/* ============================================================
   max-width: 991px
   ============================================================ */
@media screen and (max-width: 991px) {
  .badgeGrid {
    grid-column-gap: 15px;
    grid-row-gap: 15px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    width: 100%;
  }

  .statBadge {
    width: 100%;
    padding-left: 20px;
    padding-right: 20px;
  }

  .contentGrid {
    grid-template-columns: 1fr;
  }
}

/* ============================================================
   max-width: 767px
   ============================================================ */
@media screen and (max-width: 767px) {
  .heading {
    font-size: 2rem;
    line-height: 1.25;
  }

  .contentCol {
    padding: 30px;
  }
}

/* ============================================================
   max-width: 479px  (mobile)
   ============================================================ */
@media screen and (max-width: 479px) {
  .section {
    padding-top: 3rem;
    padding-bottom: 2rem;
  }

  .container {
    padding-left: 1rem;
    padding-right: 1rem;
  }

  .heading {
    font-size: 1.9rem;
    line-height: 1.25;
  }

  .subtitle {
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGridWrap {
    flex-direction: column;
    padding-left: 0;
    padding-right: 0;
  }

  .badgeGrid {
    grid-column-gap: 10px;
    grid-row-gap: 10px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    max-width: 100%;
    margin-bottom: 0;
  }

  .statBadge {
    flex-flow: column;
    width: 100%;
    align-items: center;
    padding: 10px;
  }

  .statLabel {
    text-align: center;
    font-size: 1rem;
    line-height: 16px;
  }

  .ctaRow {
    flex-direction: column;
    gap: 0.75rem;
  }

  .ctaPrimary,
  .ctaSecondary {
    width: 100%;
    justify-content: center;
    margin-left: 0;
  }

  .contentGrid {
    padding-top: 40px;
    grid-template-columns: 1fr;
  }

  .contentCol {
    padding: 24px 20px;
  }

  .contentHeading {
    font-size: 20px;
  }

  .contentPara {
    font-size: 15px;
  }
}

