import Image from 'next/image';
import { Button } from '@/components/primitives/button';
import styles from './mission-hero.module.css';

const STAT_BADGES = [
  {
    icon: '/images/webflow/Layer_1-3.svg',
    label: 'White-Label by Default',
  },
  {
    icon: '/images/webflow/Layer_1-25.svg',
    label: 'Senior-Level Team',
  },
  {
    icon: '/images/webflow/Layer_1-22.svg',
    label: 'Structured Delivery',
  },
  {
    icon: '/images/webflow/Layer_1-24.svg',
    label: 'Agency-First Workflows',
  },
] as const;

export function MissionHero() {
  return (
    <section className={styles['section']}>
      <div className={styles['container']}>
        <div className={styles['inner']}>
          {/* Badge */}
          <div className={styles['badge']}>
            <span className={styles['badgeText']}>Our Mission</span>
          </div>

          {/* Heading */}
          <h1 className={styles['heading']}>
            The White-Label Delivery Partner Agencies Can Build On
          </h1>

          {/* Subtitle */}
          <p className={styles['subtitle']}>
            Boldteq operates as your behind-the-scenes production team—delivering
            senior-level design and development under your brand, with structure,
            speed, and reliability.
          </p>

          {/* Stat badges grid */}
          <div className={styles['badgeGridWrap']}>
            <div className={styles['badgeGrid']}>
              {STAT_BADGES.map((badge) => (
                <div key={badge.label} className={styles['statBadge']}>
                  <Image
                    src={badge.icon}
                    alt={badge.label}
                    width={24}
                    height={24}
                    className={styles['statIcon']}
                    loading="eager"
                  />
                  <span className={styles['statLabel']}>{badge.label}</span>
                </div>
              ))}
            </div>
          </div>

          {/* CTA buttons */}
          <div className={styles['ctaRow']}>
            <Button href="/book-a-demo" variant="primary" size="md">
              Book a Demo
            </Button>
            <Button href="/contact" variant="secondary" size="md">
              Talk to Our Team
            </Button>
          </div>
        </div>

        {/* 2-column navy content grid */}
        <div className={styles['contentGrid']}>
          <div className={styles['contentCol']}>
            <h2 className={styles['contentHeading']}>
              To help digital agencies scale faster without hiring pressure or
              delivery chaos.
            </h2>
            <p className={styles['contentPara']}>
              Agencies don&apos;t struggle with ideas. They struggle when delivery
              becomes inconsistent as volume grows. Boldteq exists to remove that
              bottleneck—by providing a dependable backend team agencies can trust
              with execution.
            </p>
          </div>

          <div className={styles['contentCol']}>
            <h2 className={styles['contentHeading']}>Why We Built Boldteq</h2>
            <p className={styles['contentPara']}>
              As agencies grow, delivery complexity increases. Hiring slows
              momentum. Freelancers add inconsistency. Internal teams become hard
              to manage at scale.
            </p>
            <p className={styles['contentPara']}>
              As agencies grow, delivery complexity increases. Hiring slows
              momentum. Freelancers add inconsistency. Internal teams become hard
              to manage at scale.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

import Image from 'next/image';
import styles from './delivery-standards.module.css';

const CARDS = [
  {
    icon: '/images/webflow/Layer_1-35.svg',
    title: 'Consistency',
    description:
      'Repeatable delivery systems ensure stable quality across every project. Work remains consistent even as request volume increases.',
  },
  {
    icon: '/images/webflow/Layer_1-34.svg',
    title: 'Speed With Control',
    description:
      'Fast turnaround backed by structure, communication, and internal review. Delivery moves quickly without sacrificing oversight or quality.',
  },
  {
    icon: '/images/webflow/Layer_1-35.svg',
    title: 'Senior-Level Output',
    description:
      'Work executed by experienced professionals who understand agency expectations. No juniors, no trial-and-error execution.',
  },
  {
    icon: '/images/webflow/Layer_1-32.svg',
    title: 'White-Label by Default',
    description:
      'Your brand stays front-facing at all times. Boldteq remains fully invisible within your client workflows.',
  },
] as const;

export function DeliveryStandards() {
  return (
    <section className={styles['section']}>
      <div className={styles['container']}>
        {/* Header */}
        <div className={styles['header']}>
          <div className={styles['badge']}>
            <span className={styles['badgeText']}>Our Standard</span>
          </div>
          <h2 className={styles['heading']}>Our Delivery Standard</h2>
          <p className={styles['subtitle']}>
            Boldteq operates as a backend delivery system for agencies — built
            around consistency, control, and senior-level execution. Every
            project follows structured workflows designed to protect quality as
            you scale.
          </p>
        </div>

        {/* Cards grid */}
        <div className={styles['grid']}>
          {CARDS.map((card) => (
            <div key={card.title} className={styles['card']}>
              <div className={styles['iconWrap']}>
                <Image
                  src={card.icon}
                  alt={card.title}
                  width={40}
                  height={40}
                  className={styles['icon']}
                  loading="lazy"
                />
              </div>
              <h3 className={styles['cardTitle']}>{card.title}</h3>
              <p className={styles['cardDesc']}>{card.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

